import "./Data.css";

const Data = ({ comment }) => {
  const delComment = (id) => {
    fetch(`http://localhost:3001/comments/`, {
      method: "DELETE",
      body: JSON.stringify({
        id: id,
      }),
    });
    console.log("sss");
  };

  return (
    <div className="data">
      {comment.map((item, index) => {
        return (
          <div key={index}>
            <p>{item.body}</p>
            <button onClick={() => delComment(item.id)}>X</button>
          </div>
        );
      })}
    </div>
  );
};

export default Data;
